// Pre-built Savage Worlds (SWADE) NPCs, in the core-book bestiary style.
// Attributes/skills are trait-die strings; `wild` marks Wild Cards (they roll
// the d6 wild die on traits and, by the book, take 3 wounds — reflected here
// as a larger HP pool). `ac` on the entry is derived Parry; `challenge` is a
// rough tier for sorting.

import { swade, dieSides } from '../systems/swade.js';
import { slug, type NpcEntry } from './npcTypes.js';
import type { SheetData } from '../types.js';

type Attrs = [string, string, string, string, string]; // agility, smarts, spirit, strength, vigor
type Skill = [string, string];                          // name, die
/** Optional mechanics: a forced trait roll (with outcome + inflicted state)
 *  and/or an area template — resolved by the generic attack pipeline. */
interface AttackMeta {
  save?: 'agility' | 'smarts' | 'spirit' | 'strength' | 'vigor';
  onSave?: 'half' | 'negate';
  condition?: string;
  aoeShape?: 'cone' | 'sphere' | 'line';
  aoeSize?: number;
  /** SWADE blast template in tiles-beyond-target (Small 1, Medium 3, Large 5). */
  aoeHexes?: number;
  /** Armor Piercing — ignores this much of the target's Armor. */
  ap?: number;
}
type Attack = [string, 'Fighting' | 'Shooting' | 'Athletics', string, string, number, AttackMeta?]; // name, skill, damage, dtype, range ft
type Armor = [string, number, number];                  // name, armor, parryBonus

interface Row {
  name: string;
  category: string;
  tier: number;
  wild: boolean;
  attrs: Attrs;
  skills: Skill[];
  attacks: Attack[];
  armor?: Armor[];
  /** Racial traits granting a flat Toughness bonus (Size, mainly), as
   *  [name, bonus] — feeds the same derived-stat path Edges use. */
  traits?: [string, number][];
  hp: number;
  pace?: number;
  /** Comma list of damage types the engine halves (sheet `resist` field). */
  resist?: string;
  /** Comma list of damage types the engine zeroes (sheet `immune` field). */
  immune?: string;
  note?: string;
}

